10	export default function SplitPayment() {
11	  const { transactionId } = useParams<{ transactionId: string }>();
12	  const [, setLocation] = useLocation();
13	  const txnId = parseInt(transactionId);
14	
15	  const [isProcessing, setIsProcessing] = useState(false);
16	  const [currentTransaction, setCurrentTransaction] = useState<any>(null);
17	  const [splitError, setSplitError] = useState<string | null>(null);
18	
19	  // First-person state
20	  const [splitCount, setSplitCount] = useState(2);
21	  const [editMode, setEditMode] = useState(false);
22	  const [editValue, setEditValue] = useState("");
23	  const [confirmedCustom, setConfirmedCustom] = useState<string | null>(null); // null = use equal split
24	
25	  const { data: transaction, isLoading } = useQuery({
26	    queryKey: ["/api/transactions", txnId],
27	    queryFn: async () => {
28	      const response = await fetch(`/api/transactions/${txnId}`);
29	      if (!response.ok) throw new Error("Transaction not found");
30	      return response.json();
31	    },
32	    enabled: !!txnId,
33	    refetchInterval: 3000,
34	  });
35	
36	  const { data: merchant } = useQuery({
37	    queryKey: ["/api/merchants", transaction?.merchantId],
38	    queryFn: async () => {
39	      const response = await fetch(`/api/merchants/${transaction.merchantId}`);
40	      if (!response.ok) throw new Error("Merchant not found");
41	      return response.json();
42	    },
43	    enabled: !!transaction?.merchantId,
44	  });
45	
46	  useEffect(() => {
47	    if (transaction) setCurrentTransaction(transaction);
48	  }, [transaction]);
49	
50	  useEffect(() => {
51	    if (!transaction?.merchantId) return;
52	    sseClient.connect(transaction.merchantId, transaction.taptStoneId);
53	    const handleUpdate = (message: any) => {
54	      if (message.transaction?.id === txnId) {
55	        setCurrentTransaction(message.transaction);
56	        queryClient.setQueryData(["/api/transactions", txnId], message.transaction);
57	      }
58	    };
59	    sseClient.subscribe("transaction_updated", handleUpdate);
60	    return () => {
61	      sseClient.unsubscribe("transaction_updated", handleUpdate);
62	      sseClient.disconnect();
63	    };
64	  }, [transaction?.merchantId, txnId]);
65	
66	  const txn = currentTransaction || transaction;
67	  const totalAmount = txn ? parseFloat(txn.price) : 0;
68	  const isSplitSetup = txn?.isSplit === true;
69	  const completedSplits = txn?.completedSplits || 0;
70	  const totalSplits = txn?.totalSplits || splitCount;
71	  const allDone = txn?.status === "completed";
72	  const nextPersonIndex = completedSplits + 1;
73	
74	  // Equal share based on split count
75	  const equalShare = (totalAmount / (isSplitSetup ? totalSplits : splitCount)).toFixed(2);
76	
77	  // Subsequent payers: remaining amount and their share
78	  const totalPaid = isSplitSetup && txn?.splitAmount
79	    ? parseFloat(txn.splitAmount) * completedSplits
80	    : 0;
81	  const remaining = totalAmount - totalPaid;
82	  const subsequentShare = isSplitSetup
83	    ? (parseFloat(txn?.splitAmount || "0") || parseFloat(equalShare)).toFixed(2)
84	    : equalShare;
85	
86	  // What's shown as the large static amount
87	  const displayAmount = isSplitSetup
88	    ? subsequentShare
89	    : (confirmedCustom ?? equalShare);
90	
91	  // Edit step: for first person in edit mode, step by equalShare; for subsequent payers, step by their share
92	  const editStep = parseFloat(isSplitSetup ? subsequentShare : equalShare);
93	  const maxEditAmount = isSplitSetup ? remaining : totalAmount;
94	
95	  const parsedEdit = parseFloat(editValue) || 0;
96	  const isEditValid = parsedEdit > 0 && parsedEdit <= maxEditAmount + 0.01;
97	
98	  // Subsequent payer edit state
99	  const [subEditMode, setSubEditMode] = useState(false);
100	  const [subEditValue, setSubEditValue] = useState("");
101	  const [subConfirmed, setSubConfirmed] = useState<string | null>(null);
102	  const subDisplay = subConfirmed ?? subsequentShare;
103	  const parsedSubEdit = parseFloat(subEditValue) || 0;
104	  const isSubEditValid = parsedSubEdit > 0 && parsedSubEdit <= remaining + 0.01;
105	
106	  const handlePay = async () => {
107	    if (!txn) return;
108	    setSplitError(null);
109	    setIsProcessing(true);
110	    try {
111	      let payAmt: number;
112	      if (!isSplitSetup) {
113	        const response = await apiRequest("POST", `/api/transactions/${txnId}/split`, {
114	          totalSplits: splitCount,
115	        });
116	        const data = await response.json();
117	        if (data.transaction) {
118	          setCurrentTransaction(data.transaction);
119	          queryClient.setQueryData(["/api/transactions", txnId], data.transaction);
120	        }
121	        payAmt = parseFloat(displayAmount);
122	      } else {
123	        payAmt = parseFloat(subDisplay);
124	      }
125	
126	      const payRes = await fetch(`/api/transactions/${txnId}/pay`, {
127	        method: "POST",
128	        headers: { "Content-Type": "application/json" },
129	        body: JSON.stringify({ merchantId: txn.merchantId, amount: payAmt.toFixed(2) }),
130	      });
131	      if (payRes.ok) {
132	        const payData = await payRes.json();
133	        if (payData.hppUrl) {
134	          window.location.href = payData.hppUrl;
135	          return;
136	        }
